insert into public.legal_provisions (
    version_id, provision_key, sequence, heading_path, heading, label, content
)
select
    '21000000-0000-4000-8000-000000000015', item.chave, item.sequencia, item.caminho, item.titulo, item.rotulo, item.conteudo
from jsonb_to_recordset($dados$[{"chave":"art-1","sequencia":1,"caminho":["LEI DE ABUSO DE AUTORIDADE","CAPÍTULO I — DISPOSIÇÕES GERAIS"],"titulo":"CAPÍTULO I — DISPOSIÇÕES GERAIS","rotulo":"Art. 1º","conteudo":"Esta Lei define os crimes de abuso de autoridade, cometidos por agente público, servidor ou não, que, no exercício de suas funções ou a pretexto de exercê-las, abuse do poder que lhe tenha sido atribuído.\n\n§ 1º As condutas descritas nesta Lei constituem crime de abuso de autoridade quando praticadas pelo agente com a finalidade específica de prejudicar outrem ou beneficiar a si mesmo ou a terceiro, ou, ainda, por mero capricho ou satisfação pessoal.\n\n§ 2º A divergência na interpretação de lei ou na avaliação de fatos e provas não configura abuso de autoridade."},{"chave":"art-2","sequencia":2,"caminho":["LEI DE ABUSO DE AUTORIDADE","CAPÍTULO II — DOS SUJEITOS DO CRIME"],"titulo":"CAPÍTULO II — DOS SUJEITOS DO CRIME","rotulo":"Art. 2º","conteudo":"É sujeito ativo do crime de abuso de autoridade qualquer agente público, servidor ou não, da administração direta, indireta ou fundacional de qualquer dos Poderes da União, dos Estados, do Distrito Federal, dos Municípios e de Território, compreendendo, mas não se limitando a:\n\nI - servidores públicos e militares ou pessoas a eles equiparadas;\n\nII - membros do Poder Legislativo;\n\nIII - membros do Poder Executivo;\n\nIV - membros do Poder Judiciário;\n\nV - membros do Ministério Público;\n\nVI - membros dos tribunais ou conselhos de contas.\n\nParágrafo único. Reputa-se agente público, para os efeitos desta Lei, todo aquele que exerce, ainda que transitoriamente ou sem remuneração, por eleição, nomeação, designação, contratação ou qualquer outra forma de investidura ou vínculo, mandato, cargo, emprego ou função em órgão ou entidade abrangidos pelo caput deste artigo."},{"chave":"art-3","sequencia":3,"caminho":["LEI DE ABUSO DE AUTORIDADE","CAPÍTULO III — DA AÇÃO PENAL"],"titulo":"CAPÍTULO III — DA AÇÃO PENAL","rotulo":"Art. 3º","conteudo":"Os crimes previstos nesta Lei são de ação penal pública incondicionada. (Promulgação partes vetadas)\n\n§ 1º Será admitida ação privada se a ação penal pública não for intentada no prazo legal, cabendo ao Ministério Público aditar a queixa, repudiá-la e oferecer denúncia substitutiva, intervir em todos os termos do processo, fornecer elementos de prova, interpor recurso e, a todo tempo, no caso de negligência do querelante, retomar a ação como parte principal.\n\n§ 2º A ação privada subsidiária será exercida no prazo de 6 (seis) meses, contado da data em que se esgotar o prazo para oferecimento da denúncia."},{"chave":"art-4","sequencia":4,"caminho":["LEI DE ABUSO DE AUTORIDADE","CAPÍTULO IV — DOS EFEITOS DA CONDENAÇÃO E DAS PENAS RESTRITIVAS DE DIREITOS","SEÇÃO I — DOS EFEITOS DA CONDENAÇÃO"],"titulo":"SEÇÃO I — DOS EFEITOS DA CONDENAÇÃO","rotulo":"Art. 4º","conteudo":"São efeitos da condenação:\n\nI - tornar certa a obrigação de indenizar o dano causado pelo crime, devendo o juiz, a requerimento do ofendido, fixar na sentença o valor mínimo para reparação dos danos causados pela infração, considerando os prejuízos por ele sofridos;\n\nII - a inabilitação para o exercício de cargo, mandato ou função pública, pelo período de 1 (um) a 5 (cinco) anos;\n\nIII - a perda do cargo, do mandato ou da função pública.\n\nParágrafo único. Os efeitos previstos nos incisos II e III do caput deste artigo são condicionados à ocorrência de reincidência em crime de abuso de autoridade e não são automáticos, devendo ser declarados motivadamente na sentença."},{"chave":"art-5","sequencia":5,"caminho":["LEI DE ABUSO DE AUTORIDADE","CAPÍTULO IV — DOS EFEITOS DA CONDENAÇÃO E DAS PENAS RESTRITIVAS DE DIREITOS","SEÇÃO II — DAS PENAS RESTRITIVAS DE DIREITOS"],"titulo":"SEÇÃO II — DAS PENAS RESTRITIVAS DE DIREITOS","rotulo":"Art. 5º","conteudo":"As penas restritivas de direitos substitutivas das privativas de liberdade previstas nesta Lei são:\n\nI - prestação de serviços à comunidade ou a entidades públicas;\n\nII - suspensão do exercício do cargo, da função ou do mandato, pelo prazo de 1 (um) a 6 (seis) meses, com a perda dos vencimentos e das vantagens;\n\nIII - (VETADO).\n\nParágrafo único. As penas restritivas de direitos podem ser aplicadas autônoma ou cumulativamente."},{"chave":"art-6","sequencia":6,"caminho":["LEI DE ABUSO DE AUTORIDADE","CAPÍTULO V — DAS SANÇÕES DE NATUREZA CIVIL E ADMINISTRATIVA"],"titulo":"CAPÍTULO V — DAS SANÇÕES DE NATUREZA CIVIL E ADMINISTRATIVA","rotulo":"Art. 6º","conteudo":"As penas previstas nesta Lei serão aplicadas independentemente das sanções de natureza civil ou administrativa cabíveis.\n\nParágrafo único. As notícias de crimes previstos nesta Lei que descreverem falta funcional serão informadas à autoridade competente com vistas à apuração."},{"chave":"art-7","sequencia":7,"caminho":["LEI DE ABUSO DE AUTORIDADE","CAPÍTULO V — DAS SANÇÕES DE NATUREZA CIVIL E ADMINISTRATIVA"],"titulo":"CAPÍTULO V — DAS SANÇÕES DE NATUREZA CIVIL E ADMINISTRATIVA","rotulo":"Art. 7º","conteudo":"As responsabilidades civil e administrativa são independentes da criminal, não se podendo mais questionar sobre a existência ou a autoria do fato quando essas questões tenham sido decididas no juízo criminal."},{"chave":"art-8","sequencia":8,"caminho":["LEI DE ABUSO DE AUTORIDADE","CAPÍTULO V — DAS SANÇÕES DE NATUREZA CIVIL E ADMINISTRATIVA"],"titulo":"CAPÍTULO V — DAS SANÇÕES DE NATUREZA CIVIL E ADMINISTRATIVA","rotulo":"Art. 8º","conteudo":"Faz coisa julgada em âmbito cível, assim como no administrativo-disciplinar, a sentença penal que reconhecer ter sido o ato praticado em estado de necessidade, em legítima defesa, em estrito cumprimento de dever legal ou no exercício regular de direito."},{"chave":"art-9","sequencia":9,"caminho":["LEI DE ABUSO DE AUTORIDADE","CAPÍTULO VI — DOS CRIMES E DAS PENAS"],"titulo":"CAPÍTULO VI — DOS CRIMES E DAS PENAS","rotulo":"Art. 9º","conteudo":"Decretar medida de privação da liberdade em manifesta desconformidade com as hipóteses legais: (Promulgação partes vetadas)\n\nPena - detenção, de 1 (um) a 4 (quatro) anos, e multa.\n\nParágrafo único. Incorre na mesma pena a autoridade judiciária que, dentro de prazo razoável, deixar de:\n\nI - relaxar a prisão manifestamente ilegal;\n\nII - substituir a prisão preventiva por medida cautelar diversa ou de conceder liberdade provisória, quando manifestamente cabível;\n\nIII - deferir liminar ou ordem de habeas corpus , quando manifestamente cabível.’"},{"chave":"art-10","sequencia":10,"caminho":["LEI DE ABUSO DE AUTORIDADE","CAPÍTULO VI — DOS CRIMES E DAS PENAS"],"titulo":"CAPÍTULO VI — DOS CRIMES E DAS PENAS","rotulo":"Art. 10.","conteudo":"Decretar a condução coercitiva de testemunha ou investigado manifestamente descabida ou sem prévia intimação de comparecimento ao juízo:\n\nPena - detenção, de 1 (um) a 4 (quatro) anos, e multa."},{"chave":"art-11","sequencia":11,"caminho":["LEI DE ABUSO DE AUTORIDADE","CAPÍTULO VI — DOS CRIMES E DAS PENAS"],"titulo":"CAPÍTULO VI — DOS CRIMES E DAS PENAS","rotulo":"Art. 11.","conteudo":"(VETADO)."},{"chave":"art-12","sequencia":12,"caminho":["LEI DE ABUSO DE AUTORIDADE","CAPÍTULO VI — DOS CRIMES E DAS PENAS"],"titulo":"CAPÍTULO VI — DOS CRIMES E DAS PENAS","rotulo":"Art. 12.","conteudo":"Deixar injustificadamente de comunicar prisão em flagrante à autoridade judiciária no prazo legal:\n\nPena - detenção, de 6 (seis) meses a 2 (dois) anos, e multa.\n\nParágrafo único. Incorre na mesma pena quem:\n\nI - deixa de comunicar, imediatamente, a execução de prisão temporária ou preventiva à autoridade judiciária que a decretou;\n\nII - deixa de comunicar, imediatamente, a prisão de qualquer pessoa e o local onde se encontra à sua família ou à pessoa por ela indicada;\n\nIII - deixa de entregar ao preso, no prazo de 24 (vinte e quatro) horas, a nota de culpa, assinada pela autoridade, com o motivo da prisão e os nomes do condutor e das testemunhas;\n\nIV - prolonga a execução de pena privativa de liberdade, de prisão temporária, de prisão preventiva, de medida de segurança ou de internação, deixando, sem motivo justo e excepcionalíssimo, de executar o alvará de soltura imediatamente após recebido ou de promover a soltura do preso quando esgotado o prazo judicial ou legal."},{"chave":"art-13","sequencia":13,"caminho":["LEI DE ABUSO DE AUTORIDADE","CAPÍTULO VI — DOS CRIMES E DAS PENAS"],"titulo":"CAPÍTULO VI — DOS CRIMES E DAS PENAS","rotulo":"Art. 13.","conteudo":"Constranger o preso ou o detento, mediante violência, grave ameaça ou redução de sua capacidade de resistência, a:\n\nI - exibir-se ou ter seu corpo ou parte dele exibido à curiosidade pública;\n\nII - submeter-se a situação vexatória ou a constrangimento não autorizado em lei;\n\nIII - (VETADO).\n\nIII - produzir prova contra si mesmo ou contra terceiro: (Promulgação partes vetadas)\n\nPena - detenção, de 1 (um) a 4 (quatro) anos, e multa, sem prejuízo da pena cominada à violência."},{"chave":"art-14","sequencia":14,"caminho":["LEI DE ABUSO DE AUTORIDADE","CAPÍTULO VI — DOS CRIMES E DAS PENAS"],"titulo":"CAPÍTULO VI — DOS CRIMES E DAS PENAS","rotulo":"Art. 14.","conteudo":"(VETADO)."},{"chave":"art-15","sequencia":15,"caminho":["LEI DE ABUSO DE AUTORIDADE","CAPÍTULO VI — DOS CRIMES E DAS PENAS"],"titulo":"CAPÍTULO VI — DOS CRIMES E DAS PENAS","rotulo":"Art. 15.","conteudo":"Constranger a depor, sob ameaça de prisão, pessoa que, em razão de função, ministério, ofício ou profissão, deva guardar segredo ou resguardar sigilo:\n\nPena - detenção, de 1 (um) a 4 (quatro) anos, e multa.\n\nParágrafo único. (VETADO).\n\nParágrafo único. Incorre na mesma pena quem prossegue com o interrogatório: (Promulgação partes vetadas)\n\nI - de pessoa que tenha decidido exercer o direito ao silêncio; ou\n\nII - de pessoa que tenha optado por ser assistida por advogado ou defensor público, sem a presença de seu patrono."},{"chave":"art-15-a","sequencia":16,"caminho":["LEI DE ABUSO DE AUTORIDADE","CAPÍTULO VI — DOS CRIMES E DAS PENAS"],"titulo":"CAPÍTULO VI — DOS CRIMES E DAS PENAS","rotulo":"Art. 15-A","conteudo":"Submeter a vítima de infração penal ou a testemunha de crimes violentos a procedimentos desnecessários, repetitivos ou invasivos, que a leve a reviver, sem estrita necessidade: (Incluído pela Lei nº 14.321, de 2022)\n\nI - a situação de violência; ou (Incluído pela Lei nº 14.321, de 2022)\n\nII - outras situações potencialmente geradoras de sofrimento ou estigmatização: (Incluído pela Lei nº 14.321, de 2022)\n\nPena - detenção, de 3 (três) meses a 1 (um) ano, e multa. (Incluído pela Lei nº 14.321, de 2022)\n\n§ 1º Se o agente público permitir que terceiro intimide a vítima de crimes violentos, gerando indevida revitimização, aplica-se a pena aumentada de 2/3 (dois terços). (Incluído pela Lei nº 14.321, de 2022)\n\n§ 2º Se o agente público intimidar a vítima de crimes violentos, gerando indevida revitimização, aplica-se a pena em dobro. (Incluído pela Lei nº 14.321, de 2022)"},{"chave":"art-16","sequencia":17,"caminho":["LEI DE ABUSO DE AUTORIDADE","CAPÍTULO VI — DOS CRIMES E DAS PENAS"],"titulo":"CAPÍTULO VI — DOS CRIMES E DAS PENAS","rotulo":"Art. 16.","conteudo":"Deixar de identificar-se ou identificar-se falsamente ao preso por ocasião de sua captura ou quando deva fazê-lo durante sua detenção ou prisão: (Promulgação partes vetadas)\n\nPena - detenção, de 6 (seis) meses a 2 (dois) anos, e multa.\n\nParágrafo único. Incorre na mesma pena quem, como responsável por interrogatório em sede de procedimento investigatório de infração penal, deixa de identificar-se ao preso ou atribui a si mesmo falsa identidade, cargo ou função."},{"chave":"art-17","sequencia":18,"caminho":["LEI DE ABUSO DE AUTORIDADE","CAPÍTULO VI — DOS CRIMES E DAS PENAS"],"titulo":"CAPÍTULO VI — DOS CRIMES E DAS PENAS","rotulo":"Art. 17.","conteudo":"(VETADO)."},{"chave":"art-18","sequencia":19,"caminho":["LEI DE ABUSO DE AUTORIDADE","CAPÍTULO VI — DOS CRIMES E DAS PENAS"],"titulo":"CAPÍTULO VI — DOS CRIMES E DAS PENAS","rotulo":"Art. 18.","conteudo":"Submeter o preso a interrogatório policial durante o período de repouso noturno, salvo se capturado em flagrante delito ou se ele, devidamente assistido, consentir em prestar declarações:\n\nPena - detenção, de 6 (seis) meses a 2 (dois) anos, e multa."},{"chave":"art-19","sequencia":20,"caminho":["LEI DE ABUSO DE AUTORIDADE","CAPÍTULO VI — DOS CRIMES E DAS PENAS"],"titulo":"CAPÍTULO VI — DOS CRIMES E DAS PENAS","rotulo":"Art. 19.","conteudo":"Impedir ou retardar, injustificadamente, o envio de pleito de preso à autoridade judiciária competente para a apreciação da legalidade de sua prisão ou das circunstâncias de sua custódia:\n\nPena - detenção, de 1 (um) a 4 (quatro) anos, e multa.\n\nParágrafo único. Incorre na mesma pena o magistrado que, ciente do impedimento ou da demora, deixa de tomar as providências tendentes a saná-lo ou, não sendo competente para decidir sobre a prisão, deixa de enviar o pedido à autoridade judiciária que o seja."},{"chave":"art-20","sequencia":21,"caminho":["LEI DE ABUSO DE AUTORIDADE","CAPÍTULO VI — DOS CRIMES E DAS PENAS"],"titulo":"CAPÍTULO VI — DOS CRIMES E DAS PENAS","rotulo":"Art. 20.","conteudo":"Impedir, sem justa causa, a entrevista pessoal e reservada do preso com seu advogado: (Promulgação partes vetadas)\n\nPena - detenção, de 6 (seis) meses a 2 (dois) anos, e multa.\n\nParágrafo único. Incorre na mesma pena quem impede o preso, o réu solto ou o investigado de entrevistar-se pessoal e reservadamente com seu advogado ou defensor, por prazo razoável, antes de audiência judicial, e de sentar-se ao seu lado e com ele comunicar-se durante a audiência, salvo no curso de interrogatório ou no caso de audiência realizada por videoconferência."},{"chave":"art-21","sequencia":22,"caminho":["LEI DE ABUSO DE AUTORIDADE","CAPÍTULO VI — DOS CRIMES E DAS PENAS"],"titulo":"CAPÍTULO VI — DOS CRIMES E DAS PENAS","rotulo":"Art. 21.","conteudo":"Manter presos de ambos os sexos na mesma cela ou espaço de confinamento:\n\nPena - detenção, de 1 (um) a 4 (quatro) anos, e multa.\n\nParágrafo único. Incorre na mesma pena quem mantém, na mesma cela, criança ou adolescente na companhia de maior de idade ou em ambiente inadequado, observado o disposto na Lei nº 8.069, de 13 de julho de 1990 (Estatuto da Criança e do Adolescente)."},{"chave":"art-22","sequencia":23,"caminho":["LEI DE ABUSO DE AUTORIDADE","CAPÍTULO VI — DOS CRIMES E DAS PENAS"],"titulo":"CAPÍTULO VI — DOS CRIMES E DAS PENAS","rotulo":"Art. 22.","conteudo":"Invadir ou adentrar, clandestina ou astuciosamente, ou à revelia da vontade do ocupante, imóvel alheio ou suas dependências, ou nele permanecer nas mesmas condições, sem determinação judicial ou fora das condições estabelecidas em lei:\n\nPena - detenção, de 1 (um) a 4 (quatro) anos, e multa.\n\n§ 1º Incorre na mesma pena, na forma prevista no caput deste artigo, quem:\n\nI - coage alguém, mediante violência ou grave ameaça, a franquear-lhe o acesso a imóvel ou suas dependências;\n\nII - (VETADO);\n\nIII - cumpre mandado de busca e apreensão domiciliar após as 21h (vinte e uma horas) ou antes das 5h (cinco horas).\n\n§ 2º Não haverá crime se o ingresso for para prestar socorro, ou quando houver fundados indícios que indiquem a necessidade do ingresso em razão de situação de flagrante delito ou de desastre."},{"chave":"art-23","sequencia":24,"caminho":["LEI DE ABUSO DE AUTORIDADE","CAPÍTULO VI — DOS CRIMES E DAS PENAS"],"titulo":"CAPÍTULO VI — DOS CRIMES E DAS PENAS","rotulo":"Art. 23.","conteudo":"Inovar artificiosamente, no curso de diligência, de investigação ou de processo, o estado de lugar, de coisa ou de pessoa, com o fim de eximir-se de responsabilidade ou de responsabilizar criminalmente alguém ou agravar-lhe a responsabilidade:\n\nPena - detenção, de 1 (um) a 4 (quatro) anos, e multa.\n\nParágrafo único. Incorre na mesma pena quem pratica a conduta com o intuito de:\n\nI - eximir-se de responsabilidade civil ou administrativa por excesso praticado no curso de diligência;\n\nII - omitir dados ou informações ou divulgar dados ou informações incompletos para desviar o curso da investigação, da diligência ou do processo."},{"chave":"art-24","sequencia":25,"caminho":["LEI DE ABUSO DE AUTORIDADE","CAPÍTULO VI — DOS CRIMES E DAS PENAS"],"titulo":"CAPÍTULO VI — DOS CRIMES E DAS PENAS","rotulo":"Art. 24.","conteudo":"Constranger, sob violência ou grave ameaça, funcionário ou empregado de instituição hospitalar pública ou privada a admitir para tratamento pessoa cujo óbito já tenha ocorrido, com o fim de alterar local ou momento de crime, prejudicando sua apuração:\n\nPena - detenção, de 1 (um) a 4 (quatro) anos, e multa, além da pena correspondente à violência."},{"chave":"art-25","sequencia":26,"caminho":["LEI DE ABUSO DE AUTORIDADE","CAPÍTULO VI — DOS CRIMES E DAS PENAS"],"titulo":"CAPÍTULO VI — DOS CRIMES E DAS PENAS","rotulo":"Art. 25.","conteudo":"Proceder à obtenção de prova, em procedimento de investigação ou fiscalização, por meio manifestamente ilícito:\n\nPena - detenção, de 1 (um) a 4 (quatro) anos, e multa.\n\nParágrafo único. Incorre na mesma pena quem faz uso de prova, em desfavor do investigado ou fiscalizado, com prévio conhecimento de sua ilicitude."},{"chave":"art-26","sequencia":27,"caminho":["LEI DE ABUSO DE AUTORIDADE","CAPÍTULO VI — DOS CRIMES E DAS PENAS"],"titulo":"CAPÍTULO VI — DOS CRIMES E DAS PENAS","rotulo":"Art. 26.","conteudo":"(VETADO)."},{"chave":"art-27","sequencia":28,"caminho":["LEI DE ABUSO DE AUTORIDADE","CAPÍTULO VI — DOS CRIMES E DAS PENAS"],"titulo":"CAPÍTULO VI — DOS CRIMES E DAS PENAS","rotulo":"Art. 27.","conteudo":"Requisitar instauração ou instaurar procedimento investigatório de infração penal ou administrativa, em desfavor de alguém, à falta de qualquer indício da prática de crime, de ilícito funcional ou de infração administrativa: (Vide ADIN 6234) (Vide ADIN 6240)\n\nPena - detenção, de 6 (seis) meses a 2 (dois) anos, e multa.\n\nParágrafo único. Não há crime quando se tratar de sindicância ou investigação preliminar sumária, devidamente justificada."},{"chave":"art-28","sequencia":29,"caminho":["LEI DE ABUSO DE AUTORIDADE","CAPÍTULO VI — DOS CRIMES E DAS PENAS"],"titulo":"CAPÍTULO VI — DOS CRIMES E DAS PENAS","rotulo":"Art. 28.","conteudo":"Divulgar gravação ou trecho de gravação sem relação com a prova que se pretenda produzir, expondo a intimidade ou a vida privada ou ferindo a honra ou a imagem do investigado ou acusado:\n\nPena - detenção, de 1 (um) a 4 (quatro) anos, e multa."},{"chave":"art-29","sequencia":30,"caminho":["LEI DE ABUSO DE AUTORIDADE","CAPÍTULO VI — DOS CRIMES E DAS PENAS"],"titulo":"CAPÍTULO VI — DOS CRIMES E DAS PENAS","rotulo":"Art. 29.","conteudo":"Prestar informação falsa sobre procedimento judicial, policial, fiscal ou administrativo com o fim de prejudicar interesse de investigado: (Vide ADIN 6234) (Vide ADIN 6240)\n\nPena - detenção, de 6 (seis) meses a 2 (dois) anos, e multa.\n\nParágrafo único. (VETADO)."},{"chave":"art-30","sequencia":31,"caminho":["LEI DE ABUSO DE AUTORIDADE","CAPÍTULO VI — DOS CRIMES E DAS PENAS"],"titulo":"CAPÍTULO VI — DOS CRIMES E DAS PENAS","rotulo":"Art. 30.","conteudo":"Dar início ou proceder à persecução penal, civil ou administrativa sem justa causa fundamentada ou contra quem sabe inocente: (Promulgação partes vetadas)\n\nPena - detenção, de 1 (um) a 4 (quatro) anos, e multa."},{"chave":"art-31","sequencia":32,"caminho":["LEI DE ABUSO DE AUTORIDADE","CAPÍTULO VI — DOS CRIMES E DAS PENAS"],"titulo":"CAPÍTULO VI — DOS CRIMES E DAS PENAS","rotulo":"Art. 31.","conteudo":"Estender injustificadamente a investigação, procrastinando-a em prejuízo do investigado ou fiscalizado: (Vide ADIN 6234) (Vide ADIN 6240)\n\nPena - detenção, de 6 (seis) meses a 2 (dois) anos, e multa.\n\nParágrafo único. Incorre na mesma pena quem, inexistindo prazo para execução ou conclusão de procedimento, o estende de forma imotivada, procrastinando-o em prejuízo do investigado ou do fiscalizado."},{"chave":"art-32","sequencia":33,"caminho":["LEI DE ABUSO DE AUTORIDADE","CAPÍTULO VI — DOS CRIMES E DAS PENAS"],"titulo":"CAPÍTULO VI — DOS CRIMES E DAS PENAS","rotulo":"Art. 32.","conteudo":"Negar ao interessado, seu defensor ou advogado acesso aos autos de investigação preliminar, ao termo circunstanciado, ao inquérito ou a qualquer outro procedimento investigatório de infração penal, civil ou administrativa, assim como impedir a obtenção de cópias, ressalvado o acesso a peças relativas a diligências em curso, ou que indiquem a realização de diligências futuras, cujo sigilo seja imprescindível: (Promulgação partes vetadas)\n\nPena - detenção, de 6 (seis) meses a 2 (dois) anos, e multa."},{"chave":"art-33","sequencia":34,"caminho":["LEI DE ABUSO DE AUTORIDADE","CAPÍTULO VI — DOS CRIMES E DAS PENAS"],"titulo":"CAPÍTULO VI — DOS CRIMES E DAS PENAS","rotulo":"Art. 33.","conteudo":"Exigir informação ou cumprimento de obrigação, inclusive o dever de fazer ou de não fazer, sem expresso amparo legal:\n\nPena - detenção, de 6 (seis) meses a 2 (dois) anos, e multa.\n\nParágrafo único. Incorre na mesma pena quem se utiliza de cargo ou função pública ou invoca a condição de agente público para se eximir de obrigação legal ou para obter vantagem ou privilégio indevido."},{"chave":"art-34","sequencia":35,"caminho":["LEI DE ABUSO DE AUTORIDADE","CAPÍTULO VI — DOS CRIMES E DAS PENAS"],"titulo":"CAPÍTULO VI — DOS CRIMES E DAS PENAS","rotulo":"Art. 34.","conteudo":"(VETADO)."},{"chave":"art-35","sequencia":36,"caminho":["LEI DE ABUSO DE AUTORIDADE","CAPÍTULO VI — DOS CRIMES E DAS PENAS"],"titulo":"CAPÍTULO VI — DOS CRIMES E DAS PENAS","rotulo":"Art. 35.","conteudo":"(VETADO)."},{"chave":"art-36","sequencia":37,"caminho":["LEI DE ABUSO DE AUTORIDADE","CAPÍTULO VI — DOS CRIMES E DAS PENAS"],"titulo":"CAPÍTULO VI — DOS CRIMES E DAS PENAS","rotulo":"Art. 36.","conteudo":"Decretar, em processo judicial, a indisponibilidade de ativos financeiros em quantia que extrapole exacerbadamente o valor estimado para a satisfação da dívida da parte e, ante a demonstração, pela parte, da excessividade da medida, deixar de corrigi-la:\n\nPena - detenção, de 1 (um) a 4 (quatro) anos, e multa."},{"chave":"art-37","sequencia":38,"caminho":["LEI DE ABUSO DE AUTORIDADE","CAPÍTULO VI — DOS CRIMES E DAS PENAS"],"titulo":"CAPÍTULO VI — DOS CRIMES E DAS PENAS","rotulo":"Art. 37.","conteudo":"Demorar demasiada e injustificadamente no exame de processo de que tenha requerido vista em órgão colegiado, com o intuito de procrastinar seu andamento ou retardar o julgamento:\n\nPena - detenção, de 6 (seis) meses a 2 (dois) anos, e multa."},{"chave":"art-38","sequencia":39,"caminho":["LEI DE ABUSO DE AUTORIDADE","CAPÍTULO VI — DOS CRIMES E DAS PENAS"],"titulo":"CAPÍTULO VI — DOS CRIMES E DAS PENAS","rotulo":"Art. 38.","conteudo":"Antecipar o responsável pelas investigações, por meio de comunicação, inclusive rede social, atribuição de culpa, antes de concluídas as apurações e formalizada a acusação: (Promulgação partes vetadas)\n\nPena - detenção, de 6 (seis) meses a 2 (dois) anos, e multa."},{"chave":"art-39","sequencia":40,"caminho":["LEI DE ABUSO DE AUTORIDADE","CAPÍTULO VII — DO PROCEDIMENTO"],"titulo":"CAPÍTULO VII — DO PROCEDIMENTO","rotulo":"Art. 39.","conteudo":"Aplicam-se ao processo e ao julgamento dos delitos previstos nesta Lei, no que couber, as disposições do Decreto-Lei nº 3.689, de 3 de outubro de 1941 (Código de Processo Penal), e da Lei nº 9.099, de 26 de setembro de 1995."},{"chave":"art-40","sequencia":41,"caminho":["LEI DE ABUSO DE AUTORIDADE","CAPÍTULO VIII — DISPOSIÇÕES FINAIS"],"titulo":"CAPÍTULO VIII — DISPOSIÇÕES FINAIS","rotulo":"Art. 40.","conteudo":"O art. 2º da Lei nº 7.960, de 21 de dezembro de 1989 , passa a vigorar com a seguinte redação:\n\n“Art.2º .......................................................................................................\n\n........................................................................................................................\n\n§ 4º-A O mandado de prisão conterá necessariamente o período de duração da prisão temporária estabelecido no caput deste artigo, bem como o dia em que o preso deverá ser libertado.\n\n.........................................................................................................................\n\n§ 7º Decorrido o prazo contido no mandado de prisão, a autoridade responsável pela custódia deverá, independentemente de nova ordem da autoridade judicial, pôr imediatamente o preso em liberdade, salvo se já tiver sido comunicada da prorrogação da prisão temporária ou da decretação da prisão preventiva.\n\n§ 8º Inclui-se o dia do cumprimento do mandado de prisão no cômputo do prazo de prisão temporária.” (NR)"},{"chave":"art-41","sequencia":42,"caminho":["LEI DE ABUSO DE AUTORIDADE","CAPÍTULO VIII — DISPOSIÇÕES FINAIS"],"titulo":"CAPÍTULO VIII — DISPOSIÇÕES FINAIS","rotulo":"Art. 41.","conteudo":"O art. 10 da Lei nº 9.296, de 24 de julho de 1996 , passa a vigorar com a seguinte redação:\n\n“Art. 10 . Constitui crime realizar interceptação de comunicações telefônicas, de informática ou telemática, promover escuta ambiental ou quebrar segredo da Justiça, sem autorização judicial ou com objetivos não autorizados em lei:\n\nPena - reclusão, de 2 (dois) a 4 (quatro) anos, e multa.\n\nParágrafo único. Incorre na mesma pena a autoridade judicial que determina a execução de conduta prevista no caput deste artigo com objetivo não autorizado em lei.” (NR)"},{"chave":"art-42","sequencia":43,"caminho":["LEI DE ABUSO DE AUTORIDADE","CAPÍTULO VIII — DISPOSIÇÕES FINAIS"],"titulo":"CAPÍTULO VIII — DISPOSIÇÕES FINAIS","rotulo":"Art. 42.","conteudo":"A Lei nº 8.069, de 13 de julho de 1990 (Estatuto da Criança e do Adolescente), passa a vigorar acrescida do seguinte art. 227-A:\n\n“Art. 227-A Os efeitos da condenação prevista no inciso I do caput do art. 92 do Decreto-Lei nº 2.848, de 7 de dezembro de 1940 (Código Penal), para os crimes previstos nesta Lei, praticados por servidores públicos com abuso de autoridade, são condicionados à ocorrência de reincidência.\n\nParágrafo único. A perda do cargo, do mandato ou da função, nesse caso, independerá da pena aplicada na reincidência.”"},{"chave":"art-43","sequencia":44,"caminho":["LEI DE ABUSO DE AUTORIDADE","CAPÍTULO VIII — DISPOSIÇÕES FINAIS"],"titulo":"CAPÍTULO VIII — DISPOSIÇÕES FINAIS","rotulo":"Art. 43.","conteudo":"A Lei nº 8.906, de 4 de julho de 1994 , passa a vigorar acrescida do seguinte art. 7º-B: (Promulgação partes vetadas)\n\n‘Art. 7º-B Constitui crime violar direito ou prerrogativa de advogado previstos nos incisos II, III, IV e V do caput do art. 7º desta Lei:\n\nPena - detenção, de 3 (três) meses a 1 (um) ano, e multa.’”"},{"chave":"art-44","sequencia":45,"caminho":["LEI DE ABUSO DE AUTORIDADE","CAPÍTULO VIII — DISPOSIÇÕES FINAIS"],"titulo":"CAPÍTULO VIII — DISPOSIÇÕES FINAIS","rotulo":"Art. 44.","conteudo":"Revogam-se a Lei nº 4.898, de 9 de dezembro de 1965 , e o § 2º do art. 150 e o art. 350, ambos do Decreto-Lei nº 2.848, de 7 de dezembro de 1940 (Código Penal)."},{"chave":"art-45","sequencia":46,"caminho":["LEI DE ABUSO DE AUTORIDADE","CAPÍTULO VIII — DISPOSIÇÕES FINAIS"],"titulo":"CAPÍTULO VIII — DISPOSIÇÕES FINAIS","rotulo":"Art. 45.","conteudo":"Esta Lei entra em vigor após decorridos 120 (cento e vinte) dias de sua publicação oficial."}]$dados$::jsonb)
    as item(chave text, sequencia integer, caminho text[], titulo text, rotulo text, conteudo text);

